function isError(value: unknown): value is Error {
  return value instanceof Error;
}

function assertIsError(value: unknown): asserts value is Error {
  if (!isError(value)) throw new TypeError('Expected Error');
}

function handleUnknown(e: unknown) {
  // Predicate — narrow only inside if
  if (isError(e)) {
    console.log(e.stack);
  }
  // e still unknown here

  assertIsError(e);
  // e is Error here — no extra if
  console.log(e.message);
}

function fail(message: string): never {
  throw new Error(message);
}

function assertNever(value: never): never {
  throw new Error(`Unexpected value: ${JSON.stringify(value)}`);
}

type Shape = { kind: 'circle'; r: number } | { kind: 'square'; side: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case 'circle':
      return Math.PI * shape.r ** 2;
    case 'square':
      return shape.side ** 2;
    default:
      return assertNever(shape);
  }
}

type AppError =
  | { kind: 'validation'; fields: Record<string, string> }
  | { kind: 'not-found'; id: string }
  | { kind: 'timeout'; ms: number };

function httpStatus(error: AppError): number {
  switch (error.kind) {
    case 'validation':
      return 400;
    case 'not-found':
      return 404;
    case 'timeout':
      return 504;
    default: {
      const _exhaustive: never = error;
      return _exhaustive;
    }
  }
}

